from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform internal row or column that separates the two panels.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            sep = grid[r][0]
            panels = [grid[:r], grid[r + 1:]]
            break
    else:
        for c in range(1, w - 1):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1:
                sep = vals[0]
                panels = [
                    [row[:c] for row in grid],
                    [row[c + 1:] for row in grid],
                ]
                break

    def main_color(panel):
        counts = Counter(v for row in panel for v in row if v != 0)
        return counts.most_common(1)[0][0]

    colors = [main_color(panel) for panel in panels]
    chosen = max(range(2), key=lambda i: abs(colors[i] - sep))
    target = colors[chosen]
    return [[2 if v == target else v for v in row] for row in panels[chosen]]
